import{_ as o,l as r,o as e,c as n,v as t,p as s,x as i,d as p,i as h,S as d}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"接触孔、通孔与线","description":"","frontmatter":{"title":"接触孔、通孔与线","date":"2026-09-10T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/contact-via-line.md","filePath":"litho/contact-via-line.md","lastUpdated":1789023840000}'),c={name:"litho/contact-via-line.md"};function E(m,a,A,_,f,B){const l=r("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="接触孔、通孔与线" tabindex="-1">接触孔、通孔与线 <a class="header-anchor" href="#接触孔、通孔与线" aria-label="Permalink to &quot;接触孔、通孔与线&quot;">​</a></h1><div class="epigraph"><p>接触孔把有源区接到第一层金属，通孔连接相邻金属层；线在同一层内走线。孔与线是两套图形，孔更小、更吃套刻。</p><footer>—— 据 Mack, Fundamental Principles of Optical Lithography 对接触孔与通孔层作为独立图形层的整理</footer></div><p><a href="/litho/node-vs-gate-length">上一课</a>说明节点名与物理尺寸脱钩。芯片除了 <a href="/litho/interconnect-halfpitch">互连半节距与金属层</a> 的横向线，还要竖直连接。缺口：接触孔、通孔与线在图形化上各是什么，为何孔层常常比线层更难做对。没有竖直开口，横向再密的金属也接不进晶体管。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/litho/cmos-inverter-pair">CMOS 反相器为什么成对</a> 要把源漏接到电源与下一级，栅也要接到输入网。竖直方向：接触孔从有源或栅到 M1；通孔从 Mx 到 Mx+1。孔是紧凑的二维开口，套刻错一点就落到隔离上或连错相邻线。没有这套词汇，无法理解产线为何单独盯「孔层」窗口。缺口是图形种类，不是再争论节点叫什么。线解决平面连通，孔解决层间连通，缺一则网表落不到硅上。孔层窗口单独建，是因为对象本来就不是短线，套刻与开口面积才是第一约束，线宽均匀性则是线层的尺子。两类窗口不能混用同一张曝光菜单。</p><h3 id="孔不是短线" tabindex="-1">孔不是短线 <a class="header-anchor" href="#孔不是短线" aria-label="Permalink to &quot;孔不是短线&quot;">​</a></h3><p>线层的关键是节距与线宽均匀；孔层的关键是开口面积、圆度、以及相对下层的对准。把孔当成「很短的线」会用错设计规则：密集线的极限与孤立孔的极限往往不是同一条。后课单次曝光极限主要用节距说话；孔另有一套孤立图形的窗口，本课先分开对象。</p><p><span class="marginnote">接触孔：前道到 M1。通孔：金属层之间。线：同一金属层内的布线。孔的目标尺寸常常小于或相当于同层最小线宽，套刻预算常更紧。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每层仍是「定义开口 → 蚀刻或开槽 → 填金属 → 平坦化」，但掩模数据不同：线是长条网络，孔是离散阵列或稀疏点。接触必须落在有源或栅的合法着陆区；通孔必须同时打中上下两层金属。套刻把孔中心对到着陆区中心，误差直接变成电阻或开路。</p><p>孔层还常是检验与缺陷学习的先行层：开口小，同样的颗粒更容易致命，爬坡时先暴露图形化稳定性。线层则更敏感于节距与线宽均匀性。工艺窗口分开建，是因为对象本来就不是同一种多边形。本课把对象分开；如何曝光，仍然留给成像主线。</p><p>图形化动机：没有孔层，亿级晶体管无法接到金属网；没有线层，孔只是一些不相连的柱。两者缺一不可，且必须在同一套对准标记系统里串起来。</p><p><span class="marginnote">孔的工艺窗口常用曝光宽容度与焦点宽容度来画，和密集线的过程窗口形状不同。本课不画窗口，只指出对象不同，窗口才会不同。</span></p>',13)),(e(),s(d,null,{default:i(()=>[h(l,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20ACT%5B%22%E6%9C%89%E6%BA%90%E6%88%96%E6%A0%85%22%5D%20--%3E%20CT%5B%22%E6%8E%A5%E8%A7%A6%E5%AD%94%E5%9B%BE%E5%BD%A2%22%5D%0A%20%20CT%20--%3E%20M1%5B%22%E7%AC%AC%E4%B8%80%E5%B1%82%E9%87%91%E5%B1%9E%E7%BA%BF%22%5D%0A%20%20M1%20--%3E%20V1%5B%22%E9%80%9A%E5%AD%94%E5%9B%BE%E5%BD%A2%22%5D%0A%20%20V1%20--%3E%20M2%5B%22%E6%9B%B4%E9%AB%98%E9%87%91%E5%B1%9E%E7%BA%BF%22%5D%0A%20%20CT%20--%3E%20OV%5B%22%E5%A5%97%E5%88%BB%E9%A2%84%E7%AE%97%22%5D%0A%20%20V1%20--%3E%20OV%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>孔层良率往往在工艺爬坡时先亮红灯：随机缺陷更容易塞死或桥接小开口，下一课之后的缺陷密度课会回到这件事。本课只要：竖直连接与横向走线是不同的图形对象，套刻是它们之间的合同。</p><p>孔的着陆区是有限的：接触必须落在有源或栅的合法窗口内，通孔必须同时打中上下金属。套刻把三维对准收成平面上的误差椭圆；孔越小，同一纳米偏差占开口直径的比例越大，电阻分布越宽。线层的致命模式更常是桥连与断线，孔层则是开路、高阻与落到邻线的短路。两类缺陷进入同一张 <a href="/litho/yield-defect-die-area">良率</a> 账，但工艺窗口不是同一条。</p><p>不要在这里展开如何用离轴照明或孔专用掩模增强来印孔。成像主线尚未开始；本课程只说明为何必须有这些层。下一课 <a href="/litho/single-expose-limit">多重图形化之前的单次曝光极限</a> 用节距问：线层密到什么程度，一次图形化就不够。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不展开自对准接触、通孔居中或背面通孔等进阶结构。不写抗蚀剂与照明配方。也不把孔的临界尺寸塞进某一条分辨口诀。</p><p>自对准方案是为了放松套刻，不是取消孔层：图形仍然要定义，只是着陆区由侧墙或硬掩模代劳一部分对准。本课对象仍是「必须有竖直开口」。后课默认：接触孔连前道到 M1，通孔连金属层，线是同层布线；孔更吃套刻。下一课只问线/空节距的一次成像下限，仍不把成像课写完。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>接触孔连前道到 M1；通孔连金属层；线是同层布线。</li><li>孔与线是不同图形，孔更孤立、更吃套刻与开口面积。</li><li>没有孔层就没有电路；没有线层孔只是柱。</li><li>成像方法不在本课；下一课用节距谈一次图形化的下限。</li><li>套刻是孔与着陆区之间的合同，误差直接变成电阻、开路或落到邻线的短路。</li><li>出处：Mack, <em>Fundamental Principles of Optical Lithography</em>。</li></ul>',9))])}const x=o(c,[["render",E]]);export{T as __pageData,x as default};
